/**
 * AgentReview — structured post-run summary produced by every subagent run.
 *
 * Either self-reported by the agent via `subagent_review_upsert` as its
 * final action, or auto-generated by src/agents/auto-reviewer/ from the
 * run record + git diff when the agent does not self-report.
 */

export type ReviewStatus = "completed" | "aborted" | "errored" | "partial";
export type ReviewConfidence = "high" | "medium" | "low";
export type FileAction = "added" | "modified" | "deleted";

/**
 * Human oversight decision on a review. `pending` (or absent) means it is
 * still awaiting an operator verdict; `approved` / `sent_back` are the inline
 * Oversight-page actions.
 */
export type ReviewDecision = "pending" | "approved" | "sent_back";

/** Where the review came from. Drives provenance badges in the feed. */
export type ReviewSource = "self" | "auto" | "sampler" | "verifier";

export const REVIEW_DECISIONS: ReadonlyArray<ReviewDecision> = ["pending", "approved", "sent_back"];

export const REVIEW_SOURCES: ReadonlyArray<ReviewSource> = ["self", "auto", "sampler", "verifier"];

/** Per-criterion result mirrored from the independent verifier (verifier.ts). */
export type ReviewVerifierCriterion = {
  criterion: string;
  status: "pass" | "fail";
  evidence: string;
};

export type ReviewVerifier = {
  passed: boolean;
  results: ReviewVerifierCriterion[];
};

export const REVIEW_STATUSES: ReadonlyArray<ReviewStatus> = [
  "completed",
  "aborted",
  "errored",
  "partial",
];

export const REVIEW_CONFIDENCES: ReadonlyArray<ReviewConfidence> = ["high", "medium", "low"];

export type FileTouched = {
  path: string;
  action: FileAction;
  linesAdded: number;
  linesRemoved: number;
};

export type TestResults = {
  name: string;
  passed: number;
  failed: number;
  skipped: number;
};

/**
 * Verified-completion verdict mirrored from src/verification (RESULT block +
 * evidence checks + reviewer). Absent on runs reviewed before the pipeline.
 */
export type ReviewCompletion = {
  verdict: "VERIFIED" | "UNVERIFIED" | "FAILED";
  /** Terminal completion state: verified | unverified | failed | stalled | blocked | needs_input | needs_owner | accepted | rejected. */
  state: string;
  reasons: string[];
  attempts: number;
  screenshots: string[];
  visualFiles: string[];
  evidence: Array<{ kind: string; ref: string; status: string; detail: string }>;
  /** The agent's own RESULT summary (claims are in `evidence`). */
  resultSummary?: string;
  reviewedAt: number;
};

export type AgentReview = {
  /** Unique review ID (cuid-style, generated at write time). */
  id: string;
  /** Run ID from the subagent registry. Primary dedup key. */
  runId: string;
  /** Child session key of the run. Secondary index. */
  sessionKey: string;
  label?: string;
  projectId?: string;
  status: ReviewStatus;
  /** 1–3 plain sentences, 6th-grade reading level. */
  summary: string;
  filesTouched: FileTouched[];
  testsRun?: TestResults;
  buildPassed?: boolean;
  /** Up to 5 concrete next steps in plain language. */
  nextSteps: string[];
  blockers: string[];
  confidence: ReviewConfidence;
  /** LLM token cost in USD, when available. */
  tokenCost?: number;
  durationMs: number;
  completedAt: number;
  /** True when the review was self-reported by the agent (vs auto-generated). */
  selfReported?: boolean;
  /** Provenance — self / auto / sampler / verifier. Absent ⇒ infer from selfReported. */
  source?: ReviewSource;
  /** Operator oversight decision. Absent ⇒ treated as "pending". */
  decision?: ReviewDecision;
  /** Optional note attached when an operator approves / sends back. */
  decisionNote?: string;
  /** When the operator decision was recorded. */
  decidedAt?: number;
  /** Who recorded the decision (session key / display key), when known. */
  decidedBy?: string;
  /** Set by the oversight sampler when a re-check finds the work drifted. */
  drift?: boolean;
  /** Sampler/verifier note explaining the drift verdict. */
  driftNote?: string;
  /** Independent-verifier verdict, when this run was verifier-gated. */
  verifier?: ReviewVerifier;
  /** Verified-completion verdict (src/verification). */
  completion?: ReviewCompletion;
};

export function isValidReviewStatus(s: unknown): s is ReviewStatus {
  return REVIEW_STATUSES.includes(s as ReviewStatus);
}

export function isValidReviewConfidence(c: unknown): c is ReviewConfidence {
  return REVIEW_CONFIDENCES.includes(c as ReviewConfidence);
}

export function isValidReviewDecision(d: unknown): d is ReviewDecision {
  return REVIEW_DECISIONS.includes(d as ReviewDecision);
}

export function isValidReviewSource(s: unknown): s is ReviewSource {
  return REVIEW_SOURCES.includes(s as ReviewSource);
}

function parseVerifier(raw: unknown): ReviewVerifier | undefined {
  if (!raw || typeof raw !== "object") return undefined;
  const r = raw as Record<string, unknown>;
  const results: ReviewVerifierCriterion[] = Array.isArray(r.results)
    ? r.results
        .map((x): ReviewVerifierCriterion | null => {
          if (!x || typeof x !== "object") return null;
          const c = x as Record<string, unknown>;
          if (typeof c.criterion !== "string") return null;
          return {
            criterion: c.criterion,
            status: c.status === "pass" ? "pass" : "fail",
            evidence: typeof c.evidence === "string" ? c.evidence : "",
          };
        })
        .filter((x): x is ReviewVerifierCriterion => x !== null)
    : [];
  return { passed: r.passed === true, results };
}

function parseCompletion(raw: unknown): ReviewCompletion | undefined {
  if (!raw || typeof raw !== "object") return undefined;
  const r = raw as Record<string, unknown>;
  const verdict = r.verdict;
  if (verdict !== "VERIFIED" && verdict !== "UNVERIFIED" && verdict !== "FAILED") return undefined;
  const strs = (v: unknown) =>
    Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : [];
  return {
    verdict,
    state: typeof r.state === "string" ? r.state : verdict.toLowerCase(),
    reasons: strs(r.reasons),
    attempts: typeof r.attempts === "number" ? r.attempts : 1,
    screenshots: strs(r.screenshots),
    visualFiles: strs(r.visualFiles),
    evidence: Array.isArray(r.evidence)
      ? r.evidence
          .filter((e): e is Record<string, unknown> => Boolean(e) && typeof e === "object")
          .map((e) => ({
            kind: String(e.kind ?? ""),
            ref: String(e.ref ?? ""),
            status: String(e.status ?? ""),
            detail: String(e.detail ?? ""),
          }))
      : [],
    resultSummary: typeof r.resultSummary === "string" ? r.resultSummary : undefined,
    reviewedAt: typeof r.reviewedAt === "number" ? r.reviewedAt : Date.now(),
  };
}

/** Runtime guard — used in handler param validation and test assertions. */
export function isValidAgentReview(obj: unknown): obj is AgentReview {
  if (!obj || typeof obj !== "object") return false;
  const r = obj as Record<string, unknown>;
  return (
    typeof r.id === "string" &&
    r.id.length > 0 &&
    typeof r.runId === "string" &&
    r.runId.length > 0 &&
    typeof r.sessionKey === "string" &&
    isValidReviewStatus(r.status) &&
    typeof r.summary === "string" &&
    r.summary.length > 0 &&
    Array.isArray(r.filesTouched) &&
    Array.isArray(r.nextSteps) &&
    Array.isArray(r.blockers) &&
    isValidReviewConfidence(r.confidence) &&
    typeof r.durationMs === "number" &&
    typeof r.completedAt === "number"
  );
}

/** Parse and coerce a raw object into FileTouched. Returns null on failure. */
export function parseFileTouched(raw: unknown): FileTouched | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const path = typeof r.path === "string" ? r.path : null;
  const actionRaw = typeof r.action === "string" ? r.action : null;
  if (!path || !actionRaw) return null;
  const action: FileAction =
    actionRaw === "added" || actionRaw === "modified" || actionRaw === "deleted"
      ? actionRaw
      : "modified";
  return {
    path,
    action,
    linesAdded: typeof r.linesAdded === "number" ? Math.max(0, r.linesAdded) : 0,
    linesRemoved: typeof r.linesRemoved === "number" ? Math.max(0, r.linesRemoved) : 0,
  };
}

/** Parse and coerce a raw object into an AgentReview. Returns null on failure. */
export function parseAgentReview(raw: unknown): AgentReview | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  if (typeof r.id !== "string" || !r.id) return null;
  if (typeof r.runId !== "string" || !r.runId) return null;
  if (typeof r.sessionKey !== "string") return null;
  if (!isValidReviewStatus(r.status)) return null;
  if (typeof r.summary !== "string" || !r.summary) return null;
  if (!isValidReviewConfidence(r.confidence)) return null;
  if (typeof r.durationMs !== "number") return null;
  if (typeof r.completedAt !== "number") return null;

  const filesTouched: FileTouched[] = Array.isArray(r.filesTouched)
    ? r.filesTouched.map(parseFileTouched).filter((f): f is FileTouched => f !== null)
    : [];
  const nextSteps: string[] = Array.isArray(r.nextSteps)
    ? r.nextSteps.filter((s) => typeof s === "string")
    : [];
  const blockers: string[] = Array.isArray(r.blockers)
    ? r.blockers.filter((s) => typeof s === "string")
    : [];

  let testsRun: TestResults | undefined;
  if (r.testsRun && typeof r.testsRun === "object") {
    const t = r.testsRun as Record<string, unknown>;
    testsRun = {
      name: typeof t.name === "string" ? t.name : "tests",
      passed: typeof t.passed === "number" ? t.passed : 0,
      failed: typeof t.failed === "number" ? t.failed : 0,
      skipped: typeof t.skipped === "number" ? t.skipped : 0,
    };
  }

  return {
    id: r.id as string,
    runId: r.runId as string,
    sessionKey: r.sessionKey as string,
    label: typeof r.label === "string" ? r.label : undefined,
    projectId: typeof r.projectId === "string" ? r.projectId : undefined,
    status: r.status as ReviewStatus,
    summary: r.summary as string,
    filesTouched,
    testsRun,
    buildPassed: typeof r.buildPassed === "boolean" ? r.buildPassed : undefined,
    nextSteps,
    blockers,
    confidence: r.confidence as ReviewConfidence,
    tokenCost: typeof r.tokenCost === "number" ? r.tokenCost : undefined,
    durationMs: r.durationMs as number,
    completedAt: r.completedAt as number,
    selfReported: typeof r.selfReported === "boolean" ? r.selfReported : undefined,
    source: isValidReviewSource(r.source) ? r.source : undefined,
    decision: isValidReviewDecision(r.decision) ? r.decision : undefined,
    decisionNote: typeof r.decisionNote === "string" ? r.decisionNote : undefined,
    decidedAt: typeof r.decidedAt === "number" ? r.decidedAt : undefined,
    decidedBy: typeof r.decidedBy === "string" ? r.decidedBy : undefined,
    drift: typeof r.drift === "boolean" ? r.drift : undefined,
    driftNote: typeof r.driftNote === "string" ? r.driftNote : undefined,
    verifier: parseVerifier(r.verifier),
    completion: parseCompletion(r.completion),
  };
}
